#include<bits/stdc++.h>
#define int long long
using namespace std;
int id[222222];
vector<int>v[222222];
int vis[222222];
signed main(){
    ios::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n;
	cin>>n;
	for(int i=1;i<=n;i++){
		int x;
		cin>>x;
		for(int j=1;j<=x;j++){
			int y;
			cin>>y;
			v[i].push_back(y);
		}
	}
	queue<int>q;
	q.push(1);
	while(!q.empty()){
		int x=q.front();
		q.pop();
		vis[x]=1;
		for(int i=0;i<v[x].size();i++){
			if(vis[v[x][i]]==0){
				q.push(v[x][i]);				
			}

		}
	}
	for(int i=1;i<=n;i++){
		for(int j=0;j<v[i].size();j++){
			if(vis[v[i][j]]==1){
				id[v[i][j]]++;				
			}
		}
	}
	q.push(1);
	vector<int>o;
	while(!q.empty()){
		int x=q.front();
		q.pop();
		o.push_back(x);
		for(int i=0;i<v[x].size();i++){
			id[v[x][i]]--;
			if(id[v[x][i]]==0&&vis[v[x][i]]==1){
				q.push(v[x][i]);
			}
		}
	}
//	vector<int>ans;
//	for(int i=0;i<o.size();i++){
//		if(vis[o[i]]==1){
//			ans.push_back(o[i]);
//		}
//	}
//	reverse(ans.begin(),ans.end());
	reverse(o.begin(),o.end());
	for(int i=0;i<o.size();i++){
		if(o[i]==1){
			continue;
		}
		cout<<o[i]<<" ";
	}
    return 0;
}
